   [58]={next_id=59, abreast_id={}, pType =1, cg_type =0, dialog=1, msg="Neither the Abbey's traditionalists nor reformists will allow it. The reformists need this to prove commoners can be knights; the traditionalists must uphold their authority. Without irrefutable proof, who'd believe outsiders' claims?", msg_color="", msg_size=0, talker="Pope", audio="", img="arts/ui/bg/story/storybg_901.jpg", video_url="", music_id=0, background_music="", model_tid={{ 2, "4509", 0, 0},{ 3, "7152", 2, 1}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", flash_time=0, shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
